'use client';

import * as React from 'react';
import {
  Box,
  Button,
  Chip,
  Collapse,
  DataGrid,
  Divider,
  Drawer,
  Filter,
  IconButton,
  Menu,
  MenuItem,
  Navbar,
  NeofloLogo,
  Stack,
  TextField,
  ToggleButton,
  Tooltip,
  Typography,
  countActiveFilters,
} from '@neofloai/atoms';
import {
  BagSimpleIcon,
  CaretDownIcon,
  ChartLineIcon,
  ChartLineUpIcon,
  FadersHorizontalIcon,
  FileTextIcon,
  MagnifyingGlassIcon,
  QuestionIcon,
  SidebarSimpleIcon,
  SquaresFourIcon,
} from '@neofloai/atoms/icons';
import {
  border,
  elevation,
  fontWeights,
  radius,
  surface,
  text,
} from '@neofloai/atoms/tokens';

import type { FilterValue } from '@neofloai/atoms';
import { QUERY_COLUMNS, QUERY_ROWS, filterQueries } from './queries';
import { FILTER_GROUPS } from './facets';

/**
 * The folded rail. A width the rail is in, not a rung on the scale —
 * which is why it goes to size as a number and animates on its own.
 */
const RAIL_COLLAPSED_PX = 64;

/** Gutter the rail's blocks stretch between. Expanded only. */
const RAIL_GUTTER_PX = 16;

/**
 * Nav row geometry: a 28px row around a 20px glyph, at either level.
 *
 * 28 is not a ToggleButton size — the component set draws 36 and 32 — so
 * the box comes down here while the glyph stays the md size's own 20px.
 * The children take the same pair as the parents: a second level that
 * shrank its glyphs would read as a different kind of row rather than as
 * the same row indented.
 */
const NAV_ROW_PX = 28;
const NAV_GLYPH_PX = 20;

/**
 * Where the branch rule stands, and where a second-level row starts.
 * Both are measured from the left edge of the nav block rather than of
 * the rail, so the pair survives a change to the gutter.
 *
 * The rule lands between the parent's glyph and the child's, which is
 * what makes the indent read as descent rather than as a second list.
 */
const BRANCH_RULE_PX = 16;
const BRANCH_INDENT_PX = 32;

/**
 * Gap between the rail's edge and a folded parent's flyout, so the panel
 * reads as sitting beside the rail rather than as the rail widening.
 */
const FLYOUT_OFFSET_PX = 8;

/**
 * How far past its anchor the flyout has to start.
 *
 * It is anchored to the row's right edge but has to clear the rail's, and a
 * folded row is a 28px square centred in a 64px panel — so the rail's edge
 * is half the leftover width further out, and anchoring alone leaves the
 * panel overlapping the rail by that much.
 *
 * Stepping over the remainder rather than anchoring to the rail itself,
 * because the anchor is also what gives the panel its vertical position: it
 * opens level with the row it belongs to.
 */
const FLYOUT_ANCHOR_STEP_PX =
  (RAIL_COLLAPSED_PX - NAV_ROW_PX) / 2 + FLYOUT_OFFSET_PX;

/**
 * How long a folded parent's flyout survives the pointer leaving it.
 *
 * The panel stands clear of the rail, so the pointer crosses ground that
 * belongs to neither: mouseleave fires on the row and mouseenter on the
 * panel only arrives after the gap. Nothing can be put in that gap to
 * carry the hover — the rail's paper clips on the x-axis to fold its
 * labels, and the flyout's clips to scroll a long list, so a bridge from
 * either side is cut off at the edge it needs to cross.
 *
 * A timer is what is left, and it has to be generous rather than tight: a
 * reader who pauses mid-gap should not have the panel taken away.
 */
const FLYOUT_GRACE_MS = 300;

/**
 * The nav tree. One level of nesting is the whole shape — a rail that
 * needs three is a rail that needs a different navigation model.
 */
const NAV = [
  { key: 'queries', label: 'Query log', Icon: SquaresFourIcon },
  {
    key: 'invoices',
    label: 'Invoices',
    Icon: FileTextIcon,
    children: [
      { key: 'invoices-open', label: 'Open', Icon: BagSimpleIcon },
      { key: 'invoices-posted', label: 'Posted', Icon: ChartLineIcon },
    ],
  },
  { key: 'analytics', label: 'Spend analytics', Icon: ChartLineUpIcon },
];

const FOOTER_NAV = [{ key: 'help', label: 'Help', Icon: QuestionIcon }];

/**
 * Nav row colour, which a rail has to supply for itself.
 *
 * ToggleButton's neutral selected fill is surface/layers/card 2 — which
 * is exactly what Drawer paints its paper, so on a rail the selected row
 * has no fill at all and only its ink shifts. That is no fault of the
 * toggle's: its own component set sits it on a card 1 toolbar, where
 * card 2 is the first rung that reads.
 *
 * A rail needs the default ladder instead: default-hover under the
 * pointer, default-pressed once selected, the label moving from caption
 * ink to body. The same four values the shell's own sidebar binds.
 *
 * One object per scheme, so both land in a single applyStyles('dark')
 * block rather than two that would discard each other.
 */
const navRowStyles = (theme: any) => {
  const scheme = (mode: 'light' | 'dark') => ({
    color: text.default.caption[mode],
    '&:hover': { backgroundColor: surface.default.defaultHover[mode] },
    '&.Mui-selected': {
      backgroundColor: surface.default.defaultPressed[mode],
      color: text.default.body[mode],
      '&:hover': { backgroundColor: surface.default.defaultPressed[mode] },
    },
  });

  return { ...scheme('light'), ...theme.applyStyles('dark', scheme('dark')) };
};

/**
 * The parent of the page you are on: the selected row's ink and weight,
 * and no fill.
 *
 * The fill still marks exactly one row, so this is what is left to say
 * the current screen is inside this group — which matters most when the
 * group is shut and its selected child is not on screen at all.
 */
const onBranchRow = (theme: any) => ({
  color: text.default.body.light,
  ...theme.applyStyles('dark', { color: text.default.body.dark }),
});

/**
 * The flyout is its own surface rather than a Menu in Menu's clothes.
 *
 * The design draws it at 240px on 8px corners with an 8px inset. The house
 * Menu is 16px corners on a 4px inset and takes its width from its widest
 * item, which reads as a dropdown that has wandered onto the rail rather
 * than as a branch of it. Menu still does the anchoring, the dismissal and
 * the keyboard handling; the surface is this.
 *
 * Colour and elevation stay tokenised: card 1 is the nearest rung above the
 * card 2 rail, and medium is the house token for a floating panel.
 */
const FLYOUT_WIDTH_PX = 240;

const flyoutSurface = (theme: any) => ({
  width: FLYOUT_WIDTH_PX,
  maxWidth: FLYOUT_WIDTH_PX,
  borderRadius: radius.sm + 'px',
  padding: FLYOUT_OFFSET_PX + 'px',
  boxShadow: elevation.medium,
  backgroundColor: surface.layers.card1.light,
  borderColor: border.layers.card2.light,
  ...theme.applyStyles('dark', {
    backgroundColor: surface.layers.card1.dark,
    borderColor: border.layers.card2.dark,
  }),
});

/**
 * A row inside the flyout, drawn as the rail's own row rather than as a
 * menu item: a 28px pill on 4px corners, an 8px inset, an 8px glyph gap and
 * the same colour ladder — so a child reached through the flyout and the
 * same child reached in the open rail are the same object.
 */
const flyoutRow = (theme: any) => ({
  minHeight: NAV_ROW_PX,
  height: NAV_ROW_PX,
  paddingInline: FLYOUT_OFFSET_PX + 'px',
  gap: FLYOUT_OFFSET_PX + 'px',
  borderRadius: radius.xs + 'px',
  ...navRowStyles(theme),
});

/**
 * One nav row, at either level.
 *
 * A pill the width of the block expanded, a square the height of the row
 * collapsed: the fill is the part of a row the eye reads, and a wide one
 * beside a column of icons reads as a rectangle.
 *
 * Three states rather than two. selected is the page you are on and
 * onBranch is the parent of it, which are different claims and are drawn
 * differently — one takes the fill, the other only the weight.
 */
function NavRow({
  item,
  collapsed,
  selected,
  onBranch,
  expanded,
  onSelect,
  onMouseEnter,
  onMouseLeave,
}) {
  const { label, Icon, children } = item;
  return (
    /* A folded parent gets no tooltip: its flyout opens on the same hover
       and already carries the name as a header, so a tooltip would be the
       same word twice, in two panels, overlapping. */
    <Tooltip title={collapsed && !children ? label : ''} placement="right">
      <ToggleButton
        value={label}
        selected={selected}
        onChange={onSelect}
        onMouseEnter={onMouseEnter}
        onMouseLeave={onMouseLeave}
        appearance="text"
        size="md"
        // Every other folded row is named by its tooltip. This one has
        // none, so the name is stated instead of lost — a folded parent is
        // a bare glyph, and its flyout only exists once hovered.
        aria-label={collapsed && children ? label : undefined}
        aria-expanded={children && !collapsed ? expanded : undefined}
        sx={(theme) => ({
          ...navRowStyles(theme),
          height: NAV_ROW_PX,
          minHeight: NAV_ROW_PX,
          gap: 1,
          width: collapsed ? NAV_ROW_PX : '100%',
          minWidth: 0,
          alignSelf: collapsed ? 'center' : 'stretch',
          justifyContent: collapsed ? 'center' : 'flex-start',
          px: collapsed ? 0 : 1,
          textTransform: 'none',
          fontWeight: selected || onBranch ? 500 : 400,
          // The panel is mid-animation while this row is still laid out at
          // its old width. Pinning the glyph and refusing the wrap leaves
          // the label to be clipped by the panel, which is what should
          // absorb it.
          whiteSpace: 'nowrap',
          '& svg': { flexShrink: 0 },
          ...(onBranch && onBranchRow(theme)),
          // A folded parent's hover target runs to the rail's edge, not
          // just to the pill's.
          //
          // The pill is a 28px square centred in a 64px rail, so 18px of
          // bare rail sits between it and the panel it opens — and leaving
          // the pill onto that strip reads to the DOM as leaving the row
          // entirely. Without this the flyout starts closing while the
          // pointer is still travelling towards it, over the rail, which is
          // the one place it has every reason to be.
          //
          // Transparent, so the fill stays the 28px square the design
          // draws. It stops at the rail's edge because the panel clips its
          // own overflow to fold the labels; the gap beyond that is what
          // the grace period is for.
          ...(collapsed &&
            children && {
              position: 'relative',
              '&::after': {
                content: '""',
                position: 'absolute',
                top: 0,
                bottom: 0,
                left: '100%',
                width: (RAIL_COLLAPSED_PX - NAV_ROW_PX) / 2 + 'px',
              },
            }),
        })}
      >
        <Icon size={NAV_GLYPH_PX} />
        {!collapsed && label}
        {/* A parent's caret is its only trailing part, so it takes the
            slack rather than sitting in the label's gap. Folded, there is
            no slack and no label — the glyph is the whole row. */}
        {!collapsed && children && (
          <Box
            component="span"
            sx={(theme) => ({
              ml: 'auto',
              display: 'flex',
              transform: expanded ? 'none' : 'rotate(-90deg)',
              transition: theme.transitions.create('transform'),
            })}
          >
            <CaretDownIcon size={14} />
          </Box>
        )}
      </ToggleButton>
    </Tooltip>
  );
}

/**
 * A parent and the level under it.
 *
 * Expanded, the children reflow in beneath the parent behind the branch
 * rule. Folded, there is no width to indent into, so the same children
 * arrive in a flyout anchored to the parent's glyph. One level of
 * nesting, two places to put it — and the second one is why a folded
 * rail does not have to drop its nesting on the floor.
 */
function NavGroup({ item, collapsed, active, onNavigate }) {
  const onBranch = item.children.some((child) => child.key === active);
  const [expanded, setExpanded] = React.useState(onBranch);
  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

  // Arriving on the branch from anywhere else opens the group. Adjusted
  // during render rather than in an effect: it is state derived from a
  // change in active, so an effect would open the group a frame late and
  // cost a second pass. Tracking the previous value keeps it to the
  // transition — read directly, onBranch would force the group open every
  // render and a reader could never shut a group they are standing in.
  const [wasOnBranch, setWasOnBranch] = React.useState(onBranch);
  if (onBranch !== wasOnBranch) {
    setWasOnBranch(onBranch);
    if (onBranch) setExpanded(true);
  }

  /**
   * Hover, with a grace period for crossing the seam.
   *
   * Leaving the glyph and entering the flyout are two events with a gap
   * between them, so closing on mouseleave alone would shut the panel
   * before the pointer could reach it. The close is scheduled instead, and
   * the panel's own mouseenter cancels it.
   */
  const closeTimer = React.useRef(undefined);

  function holdFlyout() {
    clearTimeout(closeTimer.current);
  }

  function openFlyout(element) {
    clearTimeout(closeTimer.current);
    setAnchorEl(element);
  }

  function closeFlyout() {
    clearTimeout(closeTimer.current);
    setAnchorEl(null);
  }

  function closeFlyoutSoon() {
    clearTimeout(closeTimer.current);
    closeTimer.current = setTimeout(() => setAnchorEl(null), FLYOUT_GRACE_MS);
  }

  // A pending close outliving the component would call setState on it.
  React.useEffect(() => () => clearTimeout(closeTimer.current), []);

  function selectChild(key) {
    onNavigate(key);
    closeFlyout();
  }

  return (
    <>
      <NavRow
        item={item}
        collapsed={collapsed}
        selected={false}
        onBranch={onBranch}
        expanded={expanded}
        // Hover is how a folded rail reveals anything, so it is how the
        // flyout opens. Click still works, because hover is not available
        // to a touch screen or a keyboard.
        onMouseEnter={
          collapsed ? (event) => openFlyout(event.currentTarget) : undefined
        }
        onMouseLeave={collapsed ? closeFlyoutSoon : undefined}
        onSelect={(event) =>
          collapsed
            ? openFlyout(event.currentTarget)
            : setExpanded((previous) => !previous)
        }
      />

      {!collapsed && (
        <Collapse in={expanded}>
          <Stack
            sx={(theme) => ({
              gap: 1,
              ml: BRANCH_RULE_PX + 'px',
              pl: BRANCH_INDENT_PX - BRANCH_RULE_PX - 1 + 'px',
              borderLeft: '1px solid',
              // The default ladder, not layers. A layers/card 2 rule is a
              // rung off the rail's own card 2 fill and measures 1.06:1
              // against it — invisible, and a branch nobody can see is not
              // a branch. Same correction the selected row needs.
              borderColor: border.default.default.light,
              ...theme.applyStyles('dark', {
                borderColor: border.default.default.dark,
              }),
            })}
          >
            {item.children.map((child) => (
              <NavRow
                key={child.key}
                item={child}
                collapsed={false}
                selected={active === child.key}
                onSelect={() => onNavigate(child.key)}
              />
            ))}
          </Stack>
        </Collapse>
      )}

      {/* The flyout keeps the parent's name as a header. Folded, the
          trigger is a 16px glyph, and two rows hanging off it say
          nothing about which branch they belong to. */}
      <Menu
        anchorEl={anchorEl}
        // Gated on collapsed as well as the anchor, so expanding the rail
        // dismisses the flyout on its own. The alternative is an effect
        // clearing the anchor, which fires after the glyph it points at
        // has already moved.
        open={collapsed && anchorEl !== null}
        onClose={closeFlyout}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'left' }}
        // A hover panel must not take the pointer. The modal's backdrop
        // covers the whole viewport, so left alone it would swallow the
        // hover on every other glyph in the rail and the pointer could
        // never leave this row. The panel itself takes it back.
        sx={(theme) => ({
          pointerEvents: 'none',
          // The panel's own styles go here, not on slotProps.paper. Menu
          // paints its paper through a descendant selector, which outranks
          // the single class an sx on the paper generates — the same
          // specificity trap Drawer documents for its width. Written as the
          // same selector, so these actually land.
          '& .MuiMenu-paper': {
            pointerEvents: 'auto',
            ml: FLYOUT_ANCHOR_STEP_PX + 'px',
            ...flyoutSurface(theme),
          },
        })}
        // The flyout is not a menu the reader committed to opening, so it
        // does not take focus off the rail on hover.
        disableAutoFocusItem
        disableRestoreFocus
        slotProps={{
          paper: {
            onMouseEnter: holdFlyout,
            onMouseLeave: closeFlyoutSoon,
          },
        }}
      >
        {/* The parent's name, then a rule, then the level. The design heads
            the panel this way because the trigger is a bare glyph: without
            the name, two rows arrive from nowhere. */}
        <Box
          sx={(theme) => ({
            pb: FLYOUT_OFFSET_PX + 'px',
            mb: FLYOUT_OFFSET_PX + 'px',
            borderBottom: '1px solid',
            borderColor: border.layers.card2.light,
            ...theme.applyStyles('dark', {
              borderColor: border.layers.card2.dark,
            }),
          })}
        >
          <Typography
            variant="body2"
            noWrap
            sx={(theme) => ({
              fontWeight: fontWeights.medium,
              color: text.default.placeholder.light,
              ...theme.applyStyles('dark', {
                color: text.default.placeholder.dark,
              }),
            })}
          >
            {item.label}
          </Typography>
        </Box>
        <Stack sx={{ gap: radius.xs + 'px' }}>
          {item.children.map(({ key, label, Icon }) => (
            <MenuItem
              key={key}
              selected={active === key}
              onClick={() => selectChild(key)}
              sx={flyoutRow}
            >
              <Icon size={16} />
              {label}
            </MenuItem>
          ))}
        </Stack>
      </Menu>
    </>
  );
}

/**
 * The rail: brand, the nav it takes you around by, and a footer group
 * pinned to the bottom. Four blocks separated by space rather than rules.
 */
function NavRail({ collapsed, active, onNavigate }) {
  const block = {
    px: collapsed ? 0 : RAIL_GUTTER_PX + 'px',
    alignItems: collapsed ? 'center' : 'stretch',
  };

  return (
    <Drawer
      variant="permanent"
      size={collapsed ? RAIL_COLLAPSED_PX : 'sm'}
      slotProps={{ paper: { sx: { position: 'relative', py: 2.5 } } }}
    >
      <Stack sx={{ ...block, pb: 2, flexShrink: 0 }}>
        <Box sx={{ display: 'flex', color: 'text.primary' }}>
          <NeofloLogo variant={collapsed ? 'mark' : 'full'} size={16} />
        </Box>
      </Stack>

      {/* Takes the slack, which is what pins the footer group down. */}
      <Stack sx={{ ...block, flex: 1, minHeight: 0, gap: 1 }}>
        {NAV.map((item) =>
          item.children ? (
            <NavGroup
              key={item.key}
              item={item}
              collapsed={collapsed}
              active={active}
              onNavigate={onNavigate}
            />
          ) : (
            <NavRow
              key={item.key}
              item={item}
              collapsed={collapsed}
              selected={active === item.key}
              onSelect={() => onNavigate(item.key)}
            />
          )
        )}
      </Stack>

      <Stack sx={{ ...block, gap: 1, flexShrink: 0 }}>
        {FOOTER_NAV.map((item) => (
          <NavRow
            key={item.key}
            item={item}
            collapsed={collapsed}
            selected={active === item.key}
            onSelect={() => onNavigate(item.key)}
          />
        ))}
      </Stack>
    </Drawer>
  );
}

export default function QueryLogPage() {
  const [collapsed, setCollapsed] = React.useState(true);
  const [active, setActive] = React.useState('queries');

  const [selection, setSelection] = React.useState<FilterValue>({});
  const [search, setSearch] = React.useState('');
  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

  const activeCount = countActiveFilters(FILTER_GROUPS, selection);
  const isFiltered = activeCount > 0 || search.trim() !== '';
  const rows = filterQueries(QUERY_ROWS, search, selection);

  function clearFilters() {
    setSelection({});
    setSearch('');
  }

  /* The rail runs the full height and the bar starts where it ends, so
     the outer box is a row: rail, then a column. */
  return (
    <Stack direction="row" sx={{ height: '100vh' }}>
      <NavRail collapsed={collapsed} active={active} onNavigate={setActive} />

      <Stack sx={{ flex: 1, minWidth: 0 }}>
        {/* The bar holds the one control whose position does not move when
            the rail folds. Per-page actions go in the space after it. */}
        <Navbar>
          <IconButton
            variant="secondary"
            appearance="text"
            size="sm"
            aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            onClick={() => setCollapsed((previous) => !previous)}
          >
            <SidebarSimpleIcon />
          </IconButton>
        </Navbar>

        {/* Bands: title, toolbar, grid. The first two are as tall as what
            is in them and the grid takes everything left, so the footer
            lands on the bottom edge of the screen at any height. */}
        <Stack sx={{ flex: 1, minHeight: 0 }}>
          <Box sx={{ px: 3, py: 3 }}>
            <Typography variant="h3" component="h1">
              Query Log
            </Typography>
          </Box>
          <Divider />

          <Stack
            direction="row"
            sx={{
              px: 3,
              py: 2,
              gap: 1.5,
              alignItems: 'center',
              justifyContent: 'space-between',
            }}
          >
            <TextField
              placeholder="Search..."
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              startAdornment={<MagnifyingGlassIcon />}
              sx={{ width: 280 }}
            />
            <Stack direction="row" sx={{ gap: 1 }}>
              <Button
                variant="secondary"
                appearance="outline"
                disabled={!isFiltered}
                onClick={clearFilters}
              >
                Clear Filters
              </Button>
              <Button
                variant="secondary"
                appearance="outline"
                startIcon={<FadersHorizontalIcon />}
                onClick={(event) => setAnchorEl(event.currentTarget)}
              >
                Filter
                {activeCount > 0 && (
                  <Chip
                    size="sm"
                    variant="primary"
                    component="span"
                    label={activeCount}
                  />
                )}
              </Button>
            </Stack>
          </Stack>
          <Divider />

          {/* A definite height for the grid to be 100% of. Without the
              minHeight the rows would push the column taller than the
              screen instead of scrolling inside it. */}
          <Box sx={{ flex: 1, minHeight: 0 }}>
            <DataGrid
              size="sm"
              rows={rows}
              columns={QUERY_COLUMNS}
              rowNoun="queries"
              pageSizeOptions={[10, 25, 50]}
              initialState={{
                pagination: { paginationModel: { pageSize: 10 } },
              }}
            />
          </Box>
        </Stack>
      </Stack>

      {/* The trigger sits at the right end of the toolbar, so the panel
          hangs off its right edge — left-aligned it would run off the
          page and be pushed back in, lining up with nothing. */}
      <Filter
        groups={FILTER_GROUPS}
        value={selection}
        onChange={setSelection}
        anchorEl={anchorEl}
        open={anchorEl !== null}
        onClose={() => setAnchorEl(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      />
    </Stack>
  );
}

'use client';

import * as React from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  DataGrid,
  Divider,
  Grid,
  IconButton,
  Menu,
  MenuItem,
  NAVBAR_META_ICON_PX,
  Navbar,
  NavbarTitle,
  Select,
  Stack,
  TextField,
  Tooltip,
  Typography,
} from '@neofloai/atoms';
import {
  ArrowRightIcon,
  BuildingsIcon,
  CalendarBlankIcon,
  CaretDownIcon,
  FilePdfIcon,
  ListIcon,
  ScissorsIcon,
  TicketIcon,
  UploadSimpleIcon,
  WrenchIcon,
} from '@neofloai/atoms/icons';
import { fontFamilies, spacing, text } from '@neofloai/atoms/tokens';

import type { GridColDef } from '@neofloai/atoms';

// The rail, the record and the tax codes are the application's. The rail is
// the same workflow strip the extraction and matching screens mount, so it is
// imported rather than redrawn — a second copy would drift from the screens
// either side of this one.
import {
  AppRail,
  WORKFLOW_NAV,
  WORKFLOW_SECONDARY_NAV,
} from './AppRail';
import {
  HEADER_FIELDS,
  HEADER_META,
  LINE_ITEMS,
  VAT_CODES,
  WHT_CODES,
  formatMoney,
  formatVariance,
  isBlocked,
  money,
  simulate,
  variance,
} from './postingRecord';

import type { Finding, LineItem, TaxCode } from './postingRecord';

/** Gap between the trailing actions, as the frame draws it (Scale/250). */
const ACTION_GAP = 1.5;

/** Lines a page holds, and the choices the footer offers. */
const PAGE_SIZE = 10;
const PAGE_SIZE_OPTIONS = [10, 25, 50];

/** How long the two round trips take. Your API decides this, not the screen. */
const SIMULATE_MS = 700;
const POST_MS = 900;

/* ---------------------------------------------------------------- cells */

/**
 * The line number. Mono, and quieter than the description beside it: it is
 * the line's position rather than one of its fields, and it exists so that a
 * finding can say "line 3" and be followed.
 */
function IndexCell({ value }: { value: number }) {
  return (
    <Box
      component="span"
      sx={(theme) => ({
        fontFamily: fontFamilies.product.mono,
        fontSize: 12,
        color: text.default.placeholder.light,
        ...theme.applyStyles('dark', { color: text.default.placeholder.dark }),
      })}
    >
      {value}
    </Box>
  );
}

/**
 * A money cell: currency mark in caption ink, digits in mono, both pushed
 * right so the decimal points line up down the column. Lined-up decimals are
 * the only reason a reader can compare two figures without reading either.
 */
function AmountCell({ value }: { value: number }) {
  return (
    <Box
      component="span"
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'flex-end',
        gap: '2px',
        width: '100%',
        lineHeight: 'normal',
      }}
    >
      <Box
        component="span"
        sx={(theme) => ({
          color: text.default.placeholder.light,
          ...theme.applyStyles('dark', {
            color: text.default.placeholder.dark,
          }),
        })}
      >
        $
      </Box>
      <Box component="span" sx={{ fontFamily: fontFamilies.product.mono }}>
        {value.toLocaleString('en-US', {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        })}
      </Box>
    </Box>
  );
}

/**
 * A tax column's header: the label, its required mark, and a caret that sets
 * the code on every line at once.
 *
 * The mark is a plain asterisk. TextField draws its own in the label's ink,
 * and the frame draws both in text/error/4 — but recolouring it here would
 * make this screen's required fields look different from every other
 * screen's. The header matches what TextField does; closing the gap with the
 * frame is TextField's job, not this screen's.
 *
 * The frame draws a caret on these two headers and on none of the others,
 * which is what identifies it as a bulk control rather than a sort menu —
 * Description and Line Total are the sortable columns and they carry none. It
 * earns its place on a ten-line invoice, where every line usually takes the
 * same code and setting it row by row is ten decisions made the same way.
 */
function TaxHeader({
  label,
  options,
  onApplyAll,
}: {
  label: string;
  options: readonly TaxCode[];
  onApplyAll: (value: string) => void;
}) {
  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

  return (
    <Box
      component="span"
      sx={{ display: 'flex', alignItems: 'center', gap: '2px', minWidth: 0 }}
    >
      {label}*
      <Tooltip title={'Set ' + label + ' on every line'}>
        <IconButton
          variant="secondary"
          appearance="text"
          size="sm"
          aria-label={'Set ' + label + ' on every line'}
          onClick={(event) => setAnchorEl(event.currentTarget)}
        >
          <CaretDownIcon size={14} />
        </IconButton>
      </Tooltip>
      <Menu
        anchorEl={anchorEl}
        open={anchorEl !== null}
        onClose={() => setAnchorEl(null)}
      >
        {options.map((option) => (
          <MenuItem
            key={option.value}
            onClick={() => {
              onApplyAll(option.value);
              setAnchorEl(null);
            }}
          >
            {option.label}
          </MenuItem>
        ))}
      </Menu>
    </Box>
  );
}

/**
 * The one control on a line, and it changes with what the check found.
 *
 * Split is always available: a line covering two cost centres has to become
 * two lines before it can be posted, and that is a property of the accounting
 * rather than of anything being wrong. Fix value replaces it only on a line
 * whose arithmetic the simulate pass rejected — a repair offered on a line
 * with nothing to repair is a control that does nothing when pressed.
 */
function LineActions({
  finding,
  onFix,
  onSplit,
}: {
  finding?: Finding;
  onFix: () => void;
  onSplit: () => void;
}) {
  if (finding && finding.fix !== undefined) {
    return (
      <Tooltip title={'Set the line total to ' + formatMoney(finding.fix)}>
        <Button
          variant="error"
          appearance="outline"
          size="sm"
          startIcon={<WrenchIcon size={14} />}
          onClick={onFix}
        >
          Fix value
        </Button>
      </Tooltip>
    );
  }

  return (
    <Tooltip title="Split this line">
      <IconButton
        variant="secondary"
        appearance="text"
        size="sm"
        aria-label="Split this line"
        onClick={onSplit}
      >
        <ScissorsIcon size={16} />
      </IconButton>
    </Tooltip>
  );
}

/**
 * The upload control: the button, and a caret for the other ways a document
 * can arrive.
 *
 * The frame draws these as one split control behind a dashed edge, the border
 * doing double duty as a drop target. Atoms has no dashed appearance and no
 * split button, and faking either means overriding Button's radius and
 * Divider's border style — so this is two stock controls side by side. A
 * dashed drop zone is a Button appearance to add, not a thing to hand-roll
 * per screen.
 */
function UploadFiles() {
  const [anchorEl, setAnchorEl] = React.useState<HTMLElement | null>(null);

  return (
    <>
      <Stack direction="row" sx={{ gap: 0.5, alignItems: 'center' }}>
        <Button
          variant="secondary"
          appearance="outline"
          size="sm"
          startIcon={<UploadSimpleIcon />}
        >
          Upload Files
        </Button>
        <IconButton
          variant="secondary"
          appearance="text"
          size="sm"
          aria-label="Other ways to add a document"
          onClick={(event) => setAnchorEl(event.currentTarget)}
        >
          <CaretDownIcon />
        </IconButton>
      </Stack>
      <Menu
        anchorEl={anchorEl}
        open={anchorEl !== null}
        onClose={() => setAnchorEl(null)}
      >
        <MenuItem onClick={() => setAnchorEl(null)}>
          Upload from device
        </MenuItem>
        <MenuItem onClick={() => setAnchorEl(null)}>
          Attach from vendor portal
        </MenuItem>
      </Menu>
    </>
  );
}

/* ----------------------------------------------------------------- page */

export default function ErpPostingPage() {
  const [navOpen, setNavOpen] = React.useState(false);
  const [belowBar, setBelowBar] = React.useState<HTMLElement | null>(null);

  const [values, setValues] = React.useState<Record<string, string>>(() =>
    Object.fromEntries(HEADER_FIELDS.map((field) => [field.key, field.value]))
  );
  const [lines, setLines] = React.useState<readonly LineItem[]>(LINE_ITEMS);

  const [checking, setChecking] = React.useState(false);
  const [checked, setChecked] = React.useState(false);
  const [posting, setPosting] = React.useState(false);
  const [posted, setPosted] = React.useState(false);

  // One timer at a time: Simulate and Proceed cannot both be in flight,
  // because the second is disabled until the first has come back.
  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined
  );
  React.useEffect(() => () => clearTimeout(timer.current), []);

  /**
   * The findings are derived, not stored. Fixing a line has to clear the
   * finding that named it in the same render — a stored list goes stale the
   * moment the record changes under it, and a stale "line 3 is wrong" beside
   * a corrected line 3 is worse than no check at all.
   */
  const findings = checked ? simulate(lines) : [];
  const blocked = isBlocked(findings);
  const gap = variance(lines);

  const findingByLine = new Map<number, Finding>();
  for (const finding of findings) {
    if (finding.lineId !== undefined) {
      findingByLine.set(finding.lineId, finding);
    }
  }

  function runSimulate() {
    // Your accounting check, then the ERP's own dry run. Both answers come
    // back as one list of findings; severity is what decides whether the
    // post is blocked.
    setChecking(true);
    setPosted(false);
    timer.current = setTimeout(() => {
      setChecking(false);
      setChecked(true);
    }, SIMULATE_MS);
  }

  function runPost() {
    // Your ERP call. Nothing here can reach it until a simulate pass came
    // back clean, which is the point of the gate.
    setPosting(true);
    timer.current = setTimeout(() => {
      setPosting(false);
      setPosted(true);
    }, POST_MS);
  }

  function setLineCode(
    id: number,
    field: 'vatCode' | 'whtCode',
    code: string
  ) {
    setLines((previous) =>
      previous.map((line) =>
        line.id === id ? { ...line, [field]: code } : line
      )
    );
  }

  function applyToAll(field: 'vatCode' | 'whtCode', code: string) {
    setLines((previous) =>
      previous.map((line) => ({ ...line, [field]: code }))
    );
  }

  function fixLine(id: number) {
    setLines((previous) =>
      previous.map((line) =>
        line.id === id
          ? { ...line, lineTotal: money(line.quantity * line.unitPrice) }
          : line
      )
    );
  }

  const columns: GridColDef<LineItem>[] = [
    {
      field: 'id',
      headerName: '#',
      width: 56,
      sortable: false,
      filterable: false,
      renderCell: ({ row }) => <IndexCell value={row.id} />,
    },
    {
      field: 'description',
      headerName: 'Description',
      flex: 1.6,
      minWidth: 180,
    },
    {
      field: 'lineTotal',
      headerName: 'Line Total',
      width: 140,
      align: 'right',
      headerAlign: 'right',
      renderCell: ({ row }) => <AmountCell value={row.lineTotal} />,
    },
    {
      field: 'vatCode',
      headerName: 'VAT Tax Code',
      width: 200,
      sortable: false,
      filterable: false,
      renderHeader: () => (
        <TaxHeader
          label="VAT Tax Code"
          options={VAT_CODES}
          onApplyAll={(code) => applyToAll('vatCode', code)}
        />
      ),
      renderCell: ({ row }) => (
        <Select
          value={row.vatCode}
          onChange={(event) =>
            setLineCode(row.id, 'vatCode', event.target.value)
          }
          aria-label={'VAT tax code for line ' + row.id}
          fullWidth
        >
          {VAT_CODES.map((code) => (
            <MenuItem key={code.value} value={code.value}>
              {code.label}
            </MenuItem>
          ))}
        </Select>
      ),
    },
    {
      field: 'whtCode',
      headerName: 'WHT Tax Code',
      width: 200,
      sortable: false,
      filterable: false,
      renderHeader: () => (
        <TaxHeader
          label="WHT Tax Code"
          options={WHT_CODES}
          onApplyAll={(code) => applyToAll('whtCode', code)}
        />
      ),
      renderCell: ({ row }) => (
        <Select
          value={row.whtCode}
          onChange={(event) =>
            setLineCode(row.id, 'whtCode', event.target.value)
          }
          aria-label={'WHT tax code for line ' + row.id}
          fullWidth
        >
          {WHT_CODES.map((code) => (
            <MenuItem key={code.value} value={code.value}>
              {code.label}
            </MenuItem>
          ))}
        </Select>
      ),
    },
    {
      // No header. The column holds one control per row and the control says
      // what it does; a heading over it would name the column after whichever
      // of the two states happened to be more common.
      field: 'actions',
      headerName: '',
      width: 122,
      sortable: false,
      filterable: false,
      align: 'center',
      renderCell: ({ row }) => (
        <LineActions
          finding={findingByLine.get(row.id)}
          onFix={() => fixLine(row.id)}
          onSplit={() => {
            // Your split flow. One line becomes two, and both keep the
            // parent's tax codes until someone changes them.
          }}
        />
      ),
    },
  ];

  /* A page header, not an app bar: it spans the whole width and names the
     record, so the hamburger at its leading edge reads as "the navigation"
     rather than as the strip below it. */
  return (
    <Stack sx={{ height: '100vh', overflow: 'hidden' }}>
      <Navbar size="md">
        <IconButton
          variant="secondary"
          appearance="text"
          size="sm"
          aria-label="Open navigation"
          onClick={() => setNavOpen((previous) => !previous)}
        >
          <ListIcon />
        </IconButton>

        <NavbarTitle
          meta={[
            {
              icon: <TicketIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.ticket,
            },
            {
              // A building rather than a person: the meta line names the
              // vendor, and a vendor is a company.
              icon: <BuildingsIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.vendor,
            },
            {
              icon: <CalendarBlankIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.date,
            },
          ]}
          sx={{ ml: 3 }}
        >
          ERP Posting
        </NavbarTitle>

        <Box sx={{ flex: 1 }} />

        <Stack direction="row" sx={{ gap: ACTION_GAP, flexShrink: 0 }}>
          <Button variant="error" appearance="contained" size="sm">
            Reject
          </Button>
          <Button
            variant="secondary"
            appearance="outline"
            size="sm"
            loading={checking}
            onClick={runSimulate}
          >
            Simulate
          </Button>
          {/* Disabled until a clean pass. The label never changes and the
              button never moves — the only thing the check alters is whether
              it answers. */}
          <Tooltip
            title={
              posted
                ? 'Already posted'
                : !checked
                  ? 'Run Simulate first'
                  : blocked
                    ? 'Clear the errors below first'
                    : ''
            }
          >
            <Button
              size="sm"
              endIcon={<ArrowRightIcon size={NAVBAR_META_ICON_PX} />}
              disabled={!checked || blocked || posted}
              loading={posting}
              onClick={runPost}
            >
              Proceed
            </Button>
          </Tooltip>
        </Stack>
      </Navbar>

      {/* position: relative is what the overlay's absolute anchors to, so the
          main menu and its backdrop stop at the bar rather than running up
          over it. */}
      <Box
        ref={setBelowBar}
        sx={{
          flex: 1,
          minHeight: 0,
          display: 'flex',
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        {/* The workflow strip: sections of this record, not destinations in
            the app. No brand block and no user footer — the header above owns
            the top of the screen, and the account menu belongs to the main
            menu the hamburger brings back. */}
        <AppRail
          collapsed
          showBrand={false}
          showUser={false}
          nav={WORKFLOW_NAV}
          secondaryNav={WORKFLOW_SECONDARY_NAV}
        />

        <Stack sx={{ flex: 1, minWidth: 0, minHeight: 0 }}>
          {/* Findings sit above the form rather than beside the button that
              produced them: they are about the record, and the ones that name
              a line name one further down the page. */}
          {(findings.length > 0 || posted) && (
            <Stack sx={{ gap: 1, px: 3, pt: 2, flexShrink: 0 }}>
              {posted && (
                <Alert severity="success" floating>
                  Posted to the ERP as document 5100004821.
                </Alert>
              )}
              {/* No icon override. Alert draws one glyph for all four
                  severities on purpose — the resynced sheet puts the same
                  filled diamond in every state and changes only the colour —
                  so a per-severity glyph here would undo the component's own
                  decision. */}
              {findings.map((finding) => (
                <Alert
                  key={finding.id}
                  severity={finding.severity === 'error' ? 'error' : 'info'}
                  floating
                >
                  {finding.message}
                </Alert>
              ))}
            </Stack>
          )}

          <Box sx={{ px: 3, py: 2.5, flexShrink: 0 }}>
            {/* Eleven boxes, four across. Two kinds of field: the ones
                extraction and matching established, which are read-only here,
                and the ones the ERP needs that no earlier stage supplies. An
                editable amount would mean the invoice could change after it
                was matched; a locked posting field would mean the post could
                never be completed. */}
            <Grid container spacing={2.5}>
              {HEADER_FIELDS.map((field) => (
                <Grid key={field.key} size={{ xs: 12, sm: 6, lg: 3 }}>
                  <TextField
                    label={field.label}
                    required={field.required}
                    disabled={field.origin === 'carried'}
                    value={values[field.key] ?? ''}
                    placeholder={field.placeholder}
                    onChange={(event) =>
                      setValues((previous) => ({
                        ...previous,
                        [field.key]: event.target.value,
                      }))
                    }
                    fullWidth
                  />
                </Grid>
              ))}
              {/* Derived, so it is the one field with no entry in the record.
                  A variance you could type into would be a number you had
                  agreed with rather than one the accounting agreed with. */}
              <Grid size={{ xs: 12, sm: 6, lg: 3 }}>
                <TextField
                  label="Variance"
                  disabled
                  value={formatVariance(gap)}
                  fullWidth
                  status={checked && gap !== 0 ? 'error' : undefined}
                  helperText={
                    checked && gap !== 0
                      ? 'The lines do not add up to the invoice total'
                      : undefined
                  }
                />
              </Grid>
            </Grid>

            <Stack
              direction="row"
              sx={{ gap: 2, alignItems: 'flex-end', mt: 2 }}
            >
              <Stack sx={{ gap: 0.5 }}>
                {/* Inset to the same 8px a TextField label sits at, so this
                    block's label lines up with the ten above it. Position,
                    not restyling — the variant carries the type. */}
                <Typography
                  variant="caption"
                  sx={{ px: spacing.component.xs + 'px' }}
                >
                  Documents (1)
                </Typography>
                <UploadFiles />
              </Stack>
              <Chip
                size="sm"
                variant="secondary"
                icon={<FilePdfIcon />}
                label="Invoice-A.pdf"
              />
            </Stack>
          </Box>

          <Divider />

          {/* The grid is height: 100%, so it needs a parent with a definite
              height to be 100% of. minHeight: 0 is what makes flex: 1 mean
              "what is left" rather than "at least the rows", which would push
              the footer past the bottom edge. */}
          <Box sx={{ flex: 1, minHeight: 0 }}>
            <DataGrid
              size="sm"
              rows={lines as LineItem[]}
              columns={columns}
              rowNoun="line items"
              // The line the check rejected, tinted. The message above names
              // it; this is what makes "line 3" findable without counting.
              rowState={({ row }) =>
                findingByLine.has(row.id) ? 'error' : undefined
              }
              pageSizeOptions={PAGE_SIZE_OPTIONS}
              initialState={{
                pagination: { paginationModel: { pageSize: PAGE_SIZE } },
              }}
              disableColumnMenu
              disableRowSelectionOnClick
            />
          </Box>
        </Stack>

        {/* The main menu, floated back in over a record that stays put. The
            way out of the workflow to everything else. */}
        <AppRail
          overlay
          open={navOpen}
          onClose={() => setNavOpen(false)}
          onNavigate={() => setNavOpen(false)}
          defaultActive="dashboard"
          container={belowBar}
        />
      </Box>
    </Stack>
  );
}

'use client';

