  label: string;
  kind: 'text' | 'date' | 'money' | 'reference';
  required?: boolean;
  /** Where on the document it was read from, if it was read at all. */
  blockId?: string;
  /** Placeholder while the field is empty. Kept short enough to fit one. */
  hint?: string;
}

