/**
 * The page: the blocks on it, and a stroke around the one the selected field
 * was read from.
 *
 * The highlight is positioned in the page's own percentage coordinates, which
 * is why it survives zoom and rotation without any arithmetic of its own - it
 * is inside the thing being transformed.
 */
function DocumentPage({
  page,
  highlight,
}: {
  page: number;
  highlight?: DocumentBlock;
}) {
  const blocks = DOCUMENT_BLOCKS.filter((block) => block.page === page);

  return (
    <Box
      sx={(theme) => ({
        position: 'relative',
        width: PAGE_WIDTH_PX,
        height: PAGE_HEIGHT_PX,
        flexShrink: 0,
        overflow: 'hidden',
        backgroundColor: surface.layers.page.light,
        border: '1px solid',
        borderColor: border.layers.card2.light,
        ...theme.applyStyles('dark', {
          backgroundColor: surface.layers.page.dark,
          borderColor: border.layers.card2.dark,
        }),
      })}
    >
      {blocks.length === 0 ? (
        <Stack
          sx={{
            height: '100%',
            alignItems: 'center',
            justifyContent: 'center',
            px: 4,
          }}
        >
          <Typography variant="caption" color="text.secondary" align="center">
            {'Page ' + page + ' - nothing was extracted from this page'}
          </Typography>
        </Stack>
      ) : (
        blocks.map((block) => (
          <Box
            key={block.id}
            sx={{
              position: 'absolute',
              left: block.x + '%',
              top: block.y + '%',
              width: block.w + '%',
            }}
          >
            <Block block={block} />
          </Box>
        ))
      )}

      {highlight && highlight.page === page && (
        <Box
          aria-hidden
          sx={(theme) => ({
            position: 'absolute',
            left: highlight.x + '%',
            top: highlight.y + '%',
            width: highlight.w + '%',
            height: highlight.h + '%',
            margin: -HIGHLIGHT_INSET_PX + 'px',
            padding: HIGHLIGHT_INSET_PX + 'px',
            borderRadius: 0.5,
            border: HIGHLIGHT_WIDTH_PX + 'px solid',
            borderColor: border.primary.focus.light,
            ...theme.applyStyles('dark', {
              borderColor: border.primary.focus.dark,
            }),
          })}
        />
      )}
    </Box>
  );
}

/**
 * The viewer: a page under a toolbar.
 *
 * Zoom and rotation are one transform on the page rather than a re-layout, so
 * the box the page occupies has to be computed - a quarter turn swaps its two
 * dimensions, and without that the scroll area would reserve the wrong space
 * and clip a rotated page.
 *
 * The design draws the three toolbar clusters as joined segmented controls with
 * a shared border. Atoms has no segmented action group - ToggleButton groups
 * are for selection, and these are actions - so they are separate IconButtons
 * with the reading between them.
 */
function DocumentPane({
  page,
  onPageChange,
  highlight,
}: {
  page: number;
  onPageChange: (page: number) => void;
  highlight?: DocumentBlock;
}) {
  const [zoomIndex, setZoomIndex] = React.useState(DEFAULT_ZOOM_INDEX);
  const [rotation, setRotation] = React.useState(0);

  const zoom = ZOOM_STEPS[zoomIndex] || 1;
  const quarter = ((rotation % 360) + 360) % 360;
  const swapped = quarter === 90 || quarter === 270;
  const boxWidth = (swapped ? PAGE_HEIGHT_PX : PAGE_WIDTH_PX) * zoom;
  const boxHeight = (swapped ? PAGE_WIDTH_PX : PAGE_HEIGHT_PX) * zoom;

  return (
    <Stack
      sx={(theme) => ({
        width: DOC_PANE_WIDTH_PX,
        flexShrink: 0,
        minHeight: 0,
        backgroundColor: surface.layers.card3.light,
        ...theme.applyStyles('dark', {
          backgroundColor: surface.layers.card3.dark,
        }),
      })}
    >
      <Box
        sx={{
          flex: 1,
          minHeight: 0,
          overflow: 'auto',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'flex-start',
          p: 2,
        }}
      >
        <Box
          sx={{
            position: 'relative',
            width: boxWidth,
            height: boxHeight,
            flexShrink: 0,
          }}
        >
          <Box
            sx={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform:
                'translate(-50%, -50%) rotate(' +
                quarter +
                'deg) scale(' +
                zoom +
                ')',
            }}
          >
            <DocumentPage page={page} highlight={highlight} />
          </Box>
        </Box>
      </Box>

      <Divider />

      <Stack
        direction="row"
        sx={{
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 1,
          px: 3,
          py: 1.5,
          flexShrink: 0,
        }}
      >
        <Stack direction="row" sx={{ alignItems: 'center', gap: 0.5 }}>
          <IconButton
            variant="secondary"
            appearance="outline"
            size="sm"
            aria-label="Zoom out"
            disabled={zoomIndex === 0}
            onClick={() => setZoomIndex((index) => Math.max(0, index - 1))}
          >
            <MagnifyingGlassMinusIcon size={NAVBAR_META_ICON_PX} />
          </IconButton>
          <Typography
            variant="caption"
            sx={{ minWidth: 40, textAlign: 'center' }}
          >
            {Math.round(zoom * 100) + '%'}
          </Typography>
          <IconButton
            variant="secondary"
            appearance="outline"
            size="sm"
            aria-label="Zoom in"
            disabled={zoomIndex === ZOOM_STEPS.length - 1}
            onClick={() =>
              setZoomIndex((index) => Math.min(ZOOM_STEPS.length - 1, index + 1))
            }
          >
            <MagnifyingGlassPlusIcon size={NAVBAR_META_ICON_PX} />
          </IconButton>
        </Stack>

        <Stack direction="row" sx={{ alignItems: 'center', gap: 1 }}>
          <IconButton
            variant="secondary"
            appearance="outline"
            size="sm"
            aria-label="Rotate left"
            onClick={() => setRotation((value) => value - QUARTER_TURN_DEG)}
          >
            <ArrowCounterClockwiseIcon size={NAVBAR_META_ICON_PX} />
          </IconButton>
          <IconButton
            variant="secondary"
            appearance="outline"
            size="sm"
            aria-label="Rotate right"
            onClick={() => setRotation((value) => value + QUARTER_TURN_DEG)}
          >
            <ArrowClockwiseIcon size={NAVBAR_META_ICON_PX} />
          </IconButton>
        </Stack>

        <Stack direction="row" sx={{ alignItems: 'center', gap: 0.5 }}>
          <IconButton
            variant="secondary"
            appearance="outline"
            size="sm"
            aria-label="Previous page"
            disabled={page === 1}
            onClick={() => onPageChange(Math.max(1, page - 1))}
          >
            <CaretLeftIcon size={NAVBAR_META_ICON_PX} />
          </IconButton>
          <Typography
            variant="caption"
            sx={{ minWidth: 48, textAlign: 'center' }}
          >
            <Box component="span" sx={DIGITS}>
              {page}
            </Box>
            {' of '}
            <Box component="span" sx={DIGITS}>
              {DOCUMENT.pages}
            </Box>
          </Typography>
          <IconButton
            variant="secondary"
            appearance="outline"
            size="sm"
            aria-label="Next page"
            disabled={page === DOCUMENT.pages}
            onClick={() => onPageChange(Math.min(DOCUMENT.pages, page + 1))}
          >
            <CaretRightIcon size={NAVBAR_META_ICON_PX} />
          </IconButton>
        </Stack>
      </Stack>
    </Stack>
  );
}

/* ----------------------------------------------------------- the fields */

/**
 * A field's value, as read.
 *
 * Money is reprinted through the Currency field's own prefix rather than shown
 * as typed, so a corrected currency reaches every amount on the screen and the
 * three money rows cannot disagree about what they are denominated in.
 */
function ValueText({
  field,
  value,
  currency,
}: {
  field: ExtractedField;
  value: string;
  currency: string;
}) {
  if (value.trim() === '') {
    return (
      <Typography variant="body2" color="text.secondary">
        Not found
      </Typography>
    );
  }

  if (field.kind === 'money') {
    const parsed = parseMoney(value);
    return (
      <Box component="span" sx={DIGITS}>
        {parsed === null ? value : formatMoney(parsed, currency)}
      </Box>
    );
  }

  if (field.key === 'vendorCode' || field.key === 'vendorTaxId') {
    return (
      <Box component="span" sx={DIGITS}>
        {value}
      </Box>
    );
  }

  return <Box component="span">{value}</Box>;
}

/**
 * The metadata tab: two columns, Field and Value, as the design draws it.
 *
 * A flagged row holds an input rather than text. That is the same information
 * the design carries with a tint and a leading bar, spent on the control
 * instead - the row the screen is asking about is the row you can already type
 * in, so nobody has to discover that the cell is editable to fix the thing the
 * alert just named. Any other row becomes an input when it is clicked, because
 * extraction is the stage that corrects the document's fields and a screen that
 * can only edit its own complaints is not that stage.
 */
function MetadataTab({
  values,
  issues,
  selected,
  editing,
  currency,
  onSelect,
  onEdit,
  onChange,
  onCommit,
}: {
  values: Record<string, string>;
  issues: Issue[];
  selected: string | null;
  editing: string | null;
  currency: string;
  onSelect: (key: string) => void;
  onEdit: (key: string | null) => void;
  onChange: (key: string, value: string) => void;
  onCommit: () => void;
}) {
  const flagged = flaggedFields(issues);

  return (
    <TableContainer sx={{ height: '100%', overflow: 'auto' }}>
      <Table size="sm" sx={{ minWidth: DETAILS_TABLE_MIN_PX }}>
        <TableHead>
          <TableRow>
            <TableCell sx={[labelCell, { width: DETAILS_COLS.field }]}>
              Field
            </TableCell>
            <TableCell sx={labelCell}>Value</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {EXTRACTED_FIELDS.map((field) => {
            const value = values[field.key] || '';
            const isFlagged = flagged.has(field.key);
            const isEditing = editing === field.key;
            const showInput = isFlagged || isEditing;

            return (
              <TableRow
                key={field.key}
                hover
                selected={selected === field.key}
                // The row state, not a fill mixed at the call site. The design
                // tints the value cell alone; TableRow models the state on the
                // row, and taking the component's version keeps one vocabulary
                // across this screen and the matching one.
                state={isFlagged ? 'error' : 'default'}
                onClick={() => onSelect(field.key)}
                // One height whether the row holds a value or an input, so
                // swapping one for the other cannot step the column below it.
                sx={{ height: ROW_HEIGHT_PX }}
              >
                {/* th scope="row" because that is what this column is: the name
                    of the row rather than one of its values. The design draws it
                    with the header cell's own fill, which says the same. */}
                <TableCell component="th" scope="row" sx={labelCell}>
                  {field.label}
                  {field.required && (
                    <Box component="span" sx={requiredMark}>
                      {' *'}
                    </Box>
                  )}
                </TableCell>
                <TableCell
                  sx={{ whiteSpace: 'normal' }}
                  onClick={(event) => {
                    event.stopPropagation();
                    onSelect(field.key);
                    onEdit(field.key);
                  }}
                >
                  {showInput ? (
                    <Stack
                      direction="row"
                      sx={{ alignItems: 'center', gap: 1.5, minWidth: 0 }}
                    >
                      <TextField
                        value={value}
                        sx={{
                          width: VALUE_INPUT_WIDTH_PX,
                          flexShrink: 0,
                          maxWidth: '100%',
                        }}
                        // The hint goes in the placeholder, which is the one
                        // place it costs no row height and shows exactly when
                        // it is wanted - an empty field.
                        placeholder={
                          field.hint ||
                          (field.kind === 'money' ? '0.00' : 'Not found')
                        }
                        status={isFlagged ? 'error' : undefined}
                        autoFocus={isEditing}
                        onChange={(event) =>
                          onChange(field.key, event.target.value)
                        }
                        // A flagged row shows its input without being clicked,
                        // so it can also be reached by tabbing to it - and then
                        // the keystroke that resolves the issue would unflag the
                        // row and take the input out from under the caret. This
                        // claims the row on focus, by whatever route.
                        onFocus={() => onEdit(field.key)}
                        onBlur={onCommit}
                        onKeyDown={(event) => {
                          if (event.key === 'Enter' || event.key === 'Escape') {
                            onCommit();
                          }
                        }}
                        startAdornment={
                          field.kind === 'money' ? (
                            <Typography
                              variant="body2"
                              color="text.secondary"
                              component="span"
                            >
                              {currencyPrefix(currency)}
                            </Typography>
                          ) : undefined
                        }
                      />
                    </Stack>
                  ) : (
                    <ValueText field={field} value={value} currency={currency} />
                  )}
                </TableCell>
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

/**
 * The lines, and what they come to.
 *
 * They are here because they are the second way to reach the figure the header
 * is missing. The footer states its own subtotal and whether that agrees with
 * the net currently in the field - a verdict the tab can give on its own,
 * rather than another entry in the alert above the other tab.
 */
function LineItemsTab({
  values,
  currency,
  onSelectLines,
}: {
  values: Record<string, string>;
  currency: string;
  onSelectLines: () => void;
}) {
  const subtotal = lineSubtotal(INVOICE_LINES);
  const reconciles = linesReconcile(values, INVOICE_LINES);
  const net = parseMoney(values.netAmount || '');

  return (
    <Stack sx={{ height: '100%', minHeight: 0 }}>
      <TableContainer sx={{ flex: 1, minHeight: 0, overflow: 'auto' }}>
        <Table size="sm" sx={{ minWidth: LINE_TABLE_MIN_PX }}>
          <TableHead>
            <TableRow>
              <TableCell sx={[labelCell, { width: LINE_COLS.itemNo }]}>
                Item No.
              </TableCell>
              <TableCell sx={labelCell}>Description</TableCell>
              <TableCell sx={[labelCell, { width: LINE_COLS.qty }]}>
                Qty
              </TableCell>
              <TableCell sx={labelCell} align="right">
                Unit Price
              </TableCell>
              <TableCell sx={labelCell} align="right">
                Line Total
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {INVOICE_LINES.map((line) => (
              <TableRow key={line.id} hover onClick={onSelectLines}>
                <TableCell>
                  <Box component="span" sx={CODE_INK}>
                    {line.itemNo}
                  </Box>
                </TableCell>
                <TableCell sx={{ whiteSpace: 'normal' }}>
                  {line.description}
                </TableCell>
                <TableCell>
                  <Box component="span" sx={DIGITS}>
                    {line.quantity}
                  </Box>
                </TableCell>
                <TableCell align="right">
                  <Box component="span" sx={DIGITS}>
                    {formatAmount(line.unitPrice)}
                  </Box>
                </TableCell>
                <TableCell align="right">
                  <Box component="span" sx={DIGITS}>
                    {formatAmount(lineTotal(line))}
                  </Box>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Divider />

      <Stack
        direction="row"
        sx={{
          alignItems: 'center',
          gap: 2,
          px: 3,
          py: 2,
          flexShrink: 0,
          flexWrap: 'wrap',
        }}
      >
        <Typography variant="caption" color="text.secondary">
          {'Total line items: ' +
            INVOICE_LINES.length +
            ' - quantity ' +
            lineQuantity(INVOICE_LINES)}
        </Typography>

        <Box sx={{ flex: 1 }} />

        <Typography variant="body2">
          {'Line items total '}
          <Box component="span" sx={DIGITS}>
            {formatMoney(subtotal, currency)}
          </Box>
        </Typography>

        {/* Three answers, not two: before the net is captured the lines have
            nothing to agree or disagree with, and calling that a failure would
            put a second complaint on screen for one missing field. */}
        <Chip
          size="sm"
          variant={
            reconciles === null ? 'secondary' : reconciles ? 'success' : 'error'
          }
          label={
            reconciles === null
              ? 'Net not captured yet'
              : reconciles
                ? 'Matches the net'
                : 'Net says ' + formatMoney(net || 0, currency)
          }
        />
      </Stack>
    </Stack>
  );
}

/* ------------------------------------------------------------- the screen */

export default function ExtractionScreen() {
  const [values, setValues] =
    React.useState<Record<string, string>>(EXTRACTED_VALUES);
  const [tab, setTab] = React.useState('metadata');
  const [selected, setSelected] = React.useState<string | null>(null);
  const [editing, setEditing] = React.useState<string | null>(null);
  const [page, setPage] = React.useState(1);
  const [proceeded, setProceeded] = React.useState(false);
  const [navOpen, setNavOpen] = React.useState(false);
  const [belowBar, setBelowBar] = React.useState<HTMLElement | null>(null);

  /**
   * Which region of the page is outlined.
   *
   * Held apart from the selected row rather than derived from it, because the
   * two are not the same thing: a line item points at the grid without being a
   * field, and a field that was read from nothing selects its row while
   * outlining nothing at all.
   */
  const [highlightId, setHighlightId] = React.useState<string | null>(null);

  const issues = issuesFor(values, INVOICE_LINES);
  const currency = values.currency || '';
  const highlight = DOCUMENT_BLOCKS.find((block) => block.id === highlightId);

  /**
   * Selecting a field outlines the region it was read from and turns to that
   * page.
   *
   * The link is the point of putting the document beside the fields at all: a
   * reader checking a value against the page should not also have to find the
   * page. A field that was read from nothing clears the outline instead of
   * pointing somewhere plausible - the absence is the answer, and this is the
   * screen where two fields have it.
   */
  const selectField = (key: string) => {
    setSelected(key);
    const field = EXTRACTED_FIELDS.find((candidate) => candidate.key === key);
    const block = field ? blockFor(field) : undefined;
    setHighlightId(block ? block.id : null);
    if (block) setPage(block.page);
  };

  return (
    <Stack sx={{ height: FRAME_HEIGHT_PX, overflow: 'hidden' }}>
      <Navbar size="md">
        <IconButton
          variant="secondary"
          appearance="text"
          size="sm"
          aria-label="Open navigation"
          onClick={() => setNavOpen((previous) => !previous)}
        >
          <ListIcon />
        </IconButton>

        <NavbarTitle
          meta={[
            {
              icon: <TicketIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.ticket,
            },
            {
              icon: <BuildingsIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.vendor,
            },
            {
              icon: <CalendarBlankIcon size={NAVBAR_META_ICON_PX} />,
              label: HEADER_META.date,
            },
          ]}
          sx={{ ml: 3 }}
        >
          Extraction
        </NavbarTitle>

        <Box sx={{ flex: 1 }} />

        <Stack direction="row" sx={{ gap: ACTION_GAP, flexShrink: 0 }}>
          {/* The frame paints this label with a primary-to-purple gradient.
              Atoms has no gradient type and no assistant variant, so it is a
              stock outline button. */}
          <Button
            variant="secondary"
            appearance="outline"
            size="sm"
            startIcon={<StarFourIcon />}
          >
            Ask Neo
          </Button>
          <Button variant="error" appearance="contained" size="sm">
            Reject
          </Button>
          <Tooltip
            title={
              proceeded
                ? 'Already sent on to matching'
                : issues.length > 0
                  ? issues.length === 1
                    ? 'One issue to resolve first'
                    : issues.length + ' issues to resolve first'
                  : ''
            }
          >
            <Button
              size="sm"
              endIcon={<ArrowRightIcon size={NAVBAR_META_ICON_PX} />}
              disabled={issues.length > 0 || proceeded}
              onClick={() => setProceeded(true)}
            >
              Proceed
            </Button>
          </Tooltip>
        </Stack>
      </Navbar>

      <Box
        ref={setBelowBar}
        sx={{
          flex: 1,
          minHeight: 0,
          display: 'flex',
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        <AppRail
          collapsed
          showBrand={false}
          showUser={false}
          nav={WORKFLOW_NAV}
          secondaryNav={WORKFLOW_SECONDARY_NAV}
        />

        <DocumentPane
          page={page}
          onPageChange={setPage}
          highlight={highlight}
        />

        <Stack
          sx={(theme) => ({
            flex: 1,
            minWidth: 0,
            minHeight: 0,
            borderLeft: '1px solid',
            borderColor: border.layers.card2.light,
            ...theme.applyStyles('dark', {
              borderColor: border.layers.card2.dark,
            }),
          })}
        >
          <Stack sx={{ px: 3, pt: 2, gap: 2, flexShrink: 0 }}>
            <Typography variant="h5">Extracted data</Typography>

            {issues.length > 0 && (
              <Alert
                severity="error"
                floating
                title={
                  issues.length === 1
                    ? '1 issue found'
                    : issues.length + ' issues found'
                }
              >
                {/* A count, then the issues under it as a list. Set as the
                    alert's message so the component owns the colour and the
                    glyph; the list markup is content. */}
                <Box
                  component="ul"
                  sx={{ m: 0, pl: 2.25, display: 'grid', gap: 0.25 }}
                >
                  {issues.map((issue) => (
                    <li key={issue.key}>{issue.message}</li>
                  ))}
                </Box>
              </Alert>
            )}

            {proceeded && (
              <Alert severity="success" floating>
                Extraction confirmed. This invoice is now with matching.
              </Alert>
            )}
          </Stack>

          <Tabs
            value={tab}
            onChange={(_event, value) => setTab(value)}
            sx={{ px: 3, flexShrink: 0 }}
          >
            {/* Every issue this screen can raise is about a header field, so
                only one tab ever carries a count. A count on both would imply
                the lines can be wrong on their own, and they cannot be - they
                multiply out, and the one thing they are checked against lives
                on the other tab. */}
            <Tab
              value="metadata"
              label="Metadata"
              count={issues.length > 0 ? issues.length : undefined}
            />
            <Tab value="lines" label="Line items" />
          </Tabs>

          <Box sx={{ flex: 1, minHeight: 0 }}>
            {tab === 'metadata' ? (
              <MetadataTab
                values={values}
                issues={issues}
                selected={selected}
                editing={editing}
                currency={currency}
                onSelect={selectField}
                onEdit={setEditing}
                onChange={(key, value) =>
                  setValues((previous) => ({ ...previous, [key]: value }))
                }
                onCommit={() => setEditing(null)}
              />
            ) : (
              <LineItemsTab
                values={values}
                currency={currency}
                onSelectLines={() => {
                  const block = DOCUMENT_BLOCKS.find(
                    (candidate) => candidate.id === 'lines'
                  );
                  setSelected(null);
                  setHighlightId('lines');
                  if (block) setPage(block.page);
                }}
              />
            )}
          </Box>
        </Stack>

        <AppRail
          overlay
          open={navOpen}
          onClose={() => setNavOpen(false)}
          onNavigate={() => setNavOpen(false)}
          defaultActive="dashboard"
          container={belowBar}
        />
      </Box>
    </Stack>
  );
}

'use client';

import * as React from 'react';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  DataGrid,
  Divider,
  Filter,
  IconButton,
  Link,
  Navbar,
  Stack,
  Tab,
  Tabs,
  TextField,
  Tooltip,
  Typography,
  countActiveFilters,
} from '@neofloai/atoms';
import {
  ArrowSquareOutIcon,
  FadersHorizontalIcon,
  HeadsetIcon,
  MagnifyingGlassIcon,
  PaperclipIcon,
  SidebarSimpleIcon,
  UploadSimpleIcon,
  WarningCircleIcon,
} from '@neofloai/atoms/icons';
import { fontFamilies, text, typography } from '@neofloai/atoms/tokens';

import type { FilterValue, GridColDef } from '@neofloai/atoms';

// The rail, the invoices and the facets are the application's. The rail is
// the same one every other screen in the workflow mounts, so it is imported
// rather than redrawn — a second copy would drift from the screens the
// Review button opens.
import { AppRail } from './AppRail';
import { INVOICE_FILTER_GROUPS, filterInvoices } from './invoices';

import type { Invoice, InvoiceStage } from './invoices';

/**
 * The stage an invoice is parked at, and the chip that says so.
 *
 * This map is the screen. Every other column tells you *which* invoice; the
 * stage tells you what the invoice is waiting for, and it is the only thing
 * on the row that decides where Review takes you — extraction review,
 * match review, or the posting screen.
 *
 * The four roles are the semantic ones every other status pill in the library
 * uses — `information`, `warning`, `success`, `error` — rather than the
 * hues in the frame. Read down the column it is a progression: the machine is
 * working, a human is needed, everything is validated, a stage has failed. A
 * decorative role like `purple` or `orange` carries no state, so a reader
 * could not tell from it which of two stages was the bad one.
 */
const STAGE_META: Record<
  InvoiceStage,
  {
    label: string;
    variant: 'information' | 'warning' | 'success' | 'error';
    Icon?: typeof WarningCircleIcon;
  }
> = {
  extraction: { label: 'Extraction', variant: 'information' },
  matching: { label: 'Matching', variant: 'warning' },
  posting: { label: 'ERP Posting', variant: 'success' },
  error: { label: 'Error', variant: 'error', Icon: WarningCircleIcon },
};

/**
 * Which invoices a tab is asking for. `open` is everything still moving
 * through the workflow, including the ones that have failed — an errored
 * invoice is the most open thing on the screen, not a closed one.
 */
const TABS = [
  { value: 'open', label: 'Open' },
  { value: 'closed', label: 'Closed' },
] as const;

/** Rows a page holds, and the choices the footer offers. */
const PAGE_SIZE = 10;
const PAGE_SIZE_OPTIONS = [10, 25, 50];

/* ---------------------------------------------------------------- cells */

/**
 * Two lines in one cell: the identifier over the thing that dates it.
 *
 * A grid cell centres a single line with `line-height`, so a stack of two
 * has to centre itself. Both lines ellipsise rather than wrap — a row is 56px
 * and a wrapped vendor name would push its neighbours out of alignment.
 */
function TwoLine({
  primary,
  secondary,
}: {
  primary: React.ReactNode;
  secondary: string;
}) {
  return (
    <Box
      component="span"
      sx={{
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        minWidth: 0,
        lineHeight: typography.body.b1.leading + 'px',
      }}
    >
      <Box
        component="span"
        sx={{ overflow: 'hidden', textOverflow: 'ellipsis' }}
      >
        {primary}
      </Box>
      <Box
        component="span"
        sx={(theme) => ({
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          fontSize: typography.body.b2.size,
          lineHeight: typography.body.b2.leading + 'px',
          color: text.default.caption.light,
          ...theme.applyStyles('dark', { color: text.default.caption.dark }),
        })}
      >
        {secondary}
      </Box>
    </Box>
  );
}

/**
 * The attachment, as the file it is. Placeholder ink rather than body,
 * because the filename is provenance — you read it to confirm the row is
 * about the document you meant, not to find out anything new.
 */
function AttachmentCell({ file }: { file: string }) {
  return (
    <Box
      component="span"
      sx={(theme) => ({
        display: 'flex',
        alignItems: 'center',
        gap: 0.5,
        minWidth: 0,
        lineHeight: 'normal',
        color: text.default.placeholder.light,
        ...theme.applyStyles('dark', { color: text.default.placeholder.dark }),
      })}
    >
      <PaperclipIcon size={14} style={{ flexShrink: 0 }} />
      <Box
        component="span"
        sx={{
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap',
        }}
      >
        {file}
      </Box>
    </Box>
  );
}

/**
 * Money, right-aligned, in the mono face.
 *
 * The digits are mono so the decimal points line up down the column — that
 * alignment is the only reason a reader can compare two amounts without
 * reading either of them. The currency mark stays in the sans caption
 * colour: it is the same on every row, so giving it the same weight as the
 * figure would make every row shout the same word.
 */
function AmountCell({ amount }: { amount: number }) {
  return (
    <Box
      component="span"
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'flex-end',
        gap: 0.25,
        width: '100%',
        lineHeight: 'normal',
      }}
    >
      <Box
        component="span"
        sx={(theme) => ({
          color: text.default.placeholder.light,
          ...theme.applyStyles('dark', {
            color: text.default.placeholder.dark,
          }),
        })}
      >
        $
      </Box>
      <Box
        component="span"
        sx={{ fontFamily: fontFamilies.product.mono }}
      >
        {amount.toLocaleString('en-US', { minimumFractionDigits: 2 })}
      </Box>
    </Box>
  );
}

/**
 * The one control on the row, plus the way out of the page.
 *
 * Three states, and they are not three styles of the same button. Review is
 * the primary route into the workflow and is drawn as an outline so it does
 * not compete with Upload Invoice up in the title band; View is the same
 * shape in the neutral role, for an invoice there is nothing to decide
 * about; Processing is the same shape again, disabled, because the row will
 * become one of the other two on its own and moving the control would make
 * the table jump under a reader's cursor.
 *
 * `Review` opens the invoice at whatever stage it is stuck at — the stage
 * is on the row, so the button does not need its own label per stage.
 */
function ActionCell({
  invoice,
  onOpen,
}: {
  invoice: Invoice;
  onOpen: (id: string, target: 'panel' | 'tab') => void;
}) {
  const busy = invoice.action === 'processing';

  return (
    <Stack direction="row" sx={{ gap: 1, alignItems: 'center' }}>
      <Button
        size="sm"
        appearance="outline"
        variant={invoice.action === 'review' ? 'primary' : 'secondary'}
        disabled={busy}
        startIcon={busy ? <CircularProgress size={14} color="inherit" /> : undefined}
        onClick={() => onOpen(invoice.id, 'panel')}
        sx={{ minWidth: 88 }}
      >
        {busy ? 'Processing' : invoice.action === 'review' ? 'Review' : 'View'}
      </Button>
      <Tooltip title="Open in new tab">
        <IconButton
          size="sm"
          variant="secondary"
          appearance="text"
          disabled={busy}
          aria-label={'Open invoice ' + invoice.reference + ' in a new tab'}
          onClick={() => onOpen(invoice.id, 'tab')}
        >
          <ArrowSquareOutIcon size={16} />
        </IconButton>
      </Tooltip>
    </Stack>
  );
}

/* -------------------------------------------------------------- columns */

/**
 * Six columns: who it came from, who it is from, where it is, what it is,
 * what it is worth, and the way in.
 *
 * The identity columns flex and the three on the right are fixed, so the
 * table absorbs the rail opening and closing by giving and taking from the
 * names — never from the amount or the button, whose widths are the two
 * things a reader scans down.
 */
function invoiceColumns(
  onOpen: (id: string, target: 'panel' | 'tab') => void
): GridColDef<Invoice>[] {
  return [
    {
      field: 'reference',
      headerName: 'Source ID/ Time',
      flex: 1.4,
      minWidth: 168,
      renderCell: ({ row }) => (
        <Box
          component="span"
          sx={{
            display: 'flex',
            alignItems: 'center',
            gap: 1,
            minWidth: 0,
            lineHeight: 'normal',
