        >
          {/* The channel the invoice arrived on. A glyph rather than a
              column, because it is the same answer for most rows. */}
          <Tooltip title={row.channel}>
            <HeadsetIcon size={14} style={{ flexShrink: 0 }} />
          </Tooltip>
          <TwoLine
            primary={
              <Link
