            secondary={row.received}
          />
        </Box>
      ),
    },
    {
      field: 'vendor',
      headerName: 'Vendor / Invoice#',
      flex: 1.6,
      minWidth: 168,
      renderCell: ({ row }) => (
        <TwoLine primary={row.vendor} secondary={row.invoiceNumber} />
